import type { ThemePreset, UxIR } from "@smithable/core";
import { brandColors } from "./brand.js";
import { PRESET_TOKENS } from "./theme-presets.js";

const HEADER =
  "/* Generated by Smithable from smithable.ux.yml. Do not edit: this file is overwritten on every change. */\n";

/** Each preset's font, corner radius and shadow (docs/design/delivery/02-tokens/foundations.json). */
const FOUNDATIONS: Record<ThemePreset, { font: string; radius: string; shadow: string }> = {
  modern: { font: "Inter", radius: "12px", shadow: "0 1px 3px rgb(0 0 0 / 0.08)" },
  minimal: { font: "Inter", radius: "4px", shadow: "none" },
  playful: { font: "Nunito Sans", radius: "18px", shadow: "0 1px 3px rgb(0 0 0 / 0.08)" },
  corporate: { font: "Source Sans 3", radius: "4px", shadow: "none" },
};

/** Control and row sizes per density; touch screens always get 44 px targets. */
const DENSITY = {
  comfortable: { control: "2.75rem", row: "4rem", cell: "1rem", card: "1.5rem" },
  compact: { control: "2.25rem", row: "3.25rem", cell: "0.75rem", card: "1.25rem" },
};

/** Fonts hosted by the app itself (Fontsource, OFL); the package is added to package.json. */
export const FONT_PACKAGES: Record<string, string> = {
  Inter: "@fontsource-variable/inter",
  "Nunito Sans": "@fontsource-variable/nunito-sans",
  "Source Sans 3": "@fontsource-variable/source-sans-3",
};

/** The font the app uses: the brand's, or the preset's. */
export function themeFont(ux: UxIR): string {
  return ux.theme.font ?? FOUNDATIONS[ux.theme.preset].font;
}

/** A preset's colour tokens in one mode, with a brand colour applied when there is one. */
function tokens(ux: UxIR, mode: "light" | "dark"): Record<string, string> {
  const preset: Record<string, string> = { ...PRESET_TOKENS[ux.theme.preset][mode] };
  return ux.theme.primary
    ? { ...preset, ...brandColors(ux.theme.primary, ux.theme.preset, mode) }
    : preset;
}

/** src/theme.css: the colour, shape, font and density tokens the app kit's styles use. */
export function themeCss(ux: UxIR): string {
  const font = themeFont(ux);
  const foundation = FOUNDATIONS[ux.theme.preset];
  const density = DENSITY[ux.theme.density];
  const block = (values: Record<string, string>, indent: string) =>
    Object.entries(values)
      .map(([k, v]) => `${indent}--${k}: ${v};`)
      .join("\n");
  return `${HEADER}@import "${FONT_PACKAGES[font]}";

/* Theme: ${ux.theme.preset}${ux.theme.primary ? `, brand colour ${ux.theme.primary}` : ""}, font ${font}, ${ux.theme.density} */
:root {
${block(tokens(ux, "light"), "  ")}
  --radius: ${foundation.radius};
  --card-shadow: ${foundation.shadow};
  --font-body: "${font} Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --control-height: ${density.control};
  --row-height: ${density.row};
  --cell-padding: ${density.cell};
  --card-padding: ${density.card};
}

/* Touch screens get 44 px targets whatever the density. */
@media (pointer: coarse) {
  :root {
    --control-height: 2.75rem;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
${block(tokens(ux, "dark"), "    ")}
  }
}
`;
}
